:root{font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color-scheme:dark;background:#101314;color:#f6f2eb}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(circle at top,#26302f 0,#151919 44%,#0d1010 100%);display:grid;place-items:center;padding:32px}.shell{width:min(820px,100%)}.player{background:rgba(25,29,29,.94);border:1px solid rgba(255,255,255,.09);border-radius:24px;padding:28px;box-shadow:0 30px 80px rgba(0,0,0,.35);display:grid;gap:20px}.eyebrow{text-transform:uppercase;letter-spacing:.13em;font-size:12px;color:#b7c3bf}h1,h2{margin:0}h1{font-size:clamp(28px,5vw,48px);line-height:1}.now{display:grid;grid-template-columns:88px 1fr;gap:18px;align-items:center}.art{width:88px;aspect-ratio:1;border-radius:18px;background:linear-gradient(135deg,#d2764e,#744c8e);display:grid;place-items:center;font-size:40px}.track-copy{display:flex;flex-direction:column;gap:6px}.track-copy strong{font-size:22px}.track-copy span,.section-heading span{color:#aeb7b4}.transport{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px}button{border:1px solid rgba(255,255,255,.12);border-radius:12px;padding:11px 12px;font:inherit;font-weight:700;background:#252a29;color:#f6f2eb;cursor:pointer}button.primary{background:#f2e6d6;color:#1c2221}button[aria-pressed="true"]{outline:2px solid #d2764e;background:#3a2b25}button:disabled{opacity:.42;cursor:not-allowed}.library,.queue{padding-top:4px}.library h2,.queue h2{font-size:16px}.section-heading{display:flex;align-items:center;justify-content:space-between}.library #trackChoices{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:10px}.track-choice{text-align:left}.track-choice small{display:block;color:#aeb7b4;margin-top:3px}#queueList{list-style:none;padding:0;margin:10px 0 0;display:grid;gap:6px}#queueList li{display:grid;grid-template-columns:28px 1fr auto;align-items:center;gap:10px;padding:9px 11px;border-radius:10px;background:#202424;color:#aeb7b4}#queueList li.current{background:#302c27;color:#f6f2eb}.queue-index{font-variant-numeric:tabular-nums}.queue-state{font-size:12px;text-transform:uppercase;letter-spacing:.08em}.proof-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:8px}.proof-row{display:flex;flex-direction:column;gap:5px;padding:11px;border:1px solid rgba(255,255,255,.08);border-radius:10px;color:#b7c3bf}.proof-row strong{color:#f6f2eb}#error{color:#ffb4ab;min-height:1.2em}@media(max-width:640px){body{padding:14px}.player{padding:20px}.transport{grid-template-columns:repeat(3,minmax(0,1fr))}.library #trackChoices{grid-template-columns:1fr}.proof-grid{grid-template-columns:1fr}}

.track-card{display:grid;gap:8px;padding:10px;border-radius:12px;background:#202424}.track-card>strong{font-size:15px}.track-card>small{color:#aeb7b4}.track-actions,.queue-actions{display:flex;gap:6px;flex-wrap:wrap}.track-actions button,.queue-actions button,#clearAfterCurrent{padding:7px 9px;font-size:12px}.queue-actions{justify-content:flex-end}#queueList li{grid-template-columns:28px minmax(0,1fr) auto auto}.queue-title{min-width:0}.queue-title strong{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

.playlists{padding-top:4px}.playlists h2{font-size:16px}#playlistChoices{display:grid;gap:8px;margin-top:10px}.playlist-card{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;align-items:start;padding:12px;border-radius:12px;background:#202424}.playlist-heading{display:flex;flex-direction:column;gap:4px}.playlist-heading small{color:#aeb7b4}.playlist-entries{grid-column:1/-1;margin:0;padding-left:22px;color:#aeb7b4;font-size:13px}.playlist-entries li[data-available="false"]{opacity:.6;font-style:italic}

.explore{padding-top:4px}.explore h2{font-size:16px}.explore-actions{display:flex;gap:6px}.explore-actions button{padding:7px 9px;font-size:12px}#exploreCandidates{display:grid;gap:8px;margin-top:10px}.explore-card{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;padding:12px;border-radius:12px;background:#202424}.explore-copy{display:flex;flex-direction:column;gap:4px;min-width:0}.explore-copy strong,.explore-copy small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.explore-copy small,.explore-meta{color:#aeb7b4}.explore-meta{font-size:12px}.explore-card-actions{display:flex;gap:6px;align-items:start}.explore-card-actions button{padding:7px 9px;font-size:12px}#explorePreview{width:100%;min-height:260px;border:0;border-radius:12px;margin-top:10px;background:#090b0b}

.import-review,.imports{padding-top:4px}.import-review h2,.imports h2{font-size:16px}.import-review{display:grid;gap:12px;padding:14px;border:1px solid rgba(255,255,255,.08);border-radius:14px;background:#171b1a}.import-review[hidden]{display:none}.import-review-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.import-review-grid>div,.import-review-grid>label{display:flex;flex-direction:column;gap:5px}.import-review-grid label>span,.import-note,.muted{color:#aeb7b4;font-size:13px}.import-review input,.import-review select{width:100%;border:1px solid rgba(255,255,255,.12);border-radius:10px;padding:9px 10px;background:#202424;color:#f6f2eb;font:inherit}.import-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.import-actions span{color:#aeb7b4;font-size:13px;flex:1}.import-section{display:grid;grid-template-columns:auto 72px minmax(0,1fr) minmax(0,1fr);gap:8px;align-items:center;padding:8px 0;border-top:1px solid rgba(255,255,255,.06)}#importSections:empty{display:none}#importJobs{display:grid;gap:8px;margin-top:10px}.import-job{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;align-items:center;padding:11px 12px;border-radius:12px;background:#202424}.import-job-copy{display:flex;flex-direction:column;gap:3px;min-width:0}.import-job-copy span,.import-job-copy small{color:#aeb7b4;overflow:hidden;text-overflow:ellipsis}.import-job-progress{font-variant-numeric:tabular-nums;color:#f6f2eb}.import-job-actions{grid-column:1/-1;display:flex;gap:6px;flex-wrap:wrap}.import-job-actions button,#importReviewClose,#importRefresh{padding:7px 9px;font-size:12px}@media(max-width:640px){.import-review-grid{grid-template-columns:1fr}.import-section{grid-template-columns:auto 58px minmax(0,1fr)}.import-section input[data-import-section-artist]{grid-column:3}.import-job{grid-template-columns:minmax(0,1fr) auto}}

.app-identity{display:flex;align-items:flex-start;justify-content:space-between;gap:18px}.app-identity>div{min-width:0}.app-identity #buildIdentity{margin-top:6px;font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:min(620px,70vw)}#exitVexStream{flex:0 0 auto}body.exited .player>*:not(.app-identity){opacity:.45;pointer-events:none}

.sr-only{position:absolute!important;width:1px!important;height:1px!important;padding:0!important;margin:-1px!important;overflow:hidden!important;clip:rect(0,0,0,0)!important;white-space:nowrap!important;border:0!important}.library,.sources{padding-top:4px}.library-toolbar{display:grid;grid-template-columns:minmax(0,1.8fr) minmax(140px,.7fr) minmax(150px,.8fr);gap:8px;margin-top:10px}.library-toolbar input,.library-toolbar select{width:100%;border:1px solid rgba(255,255,255,.12);border-radius:10px;padding:9px 10px;background:#202424;color:#f6f2eb;font:inherit}.library-view-toggle,.source-actions,.source-row-actions{display:flex;gap:6px;flex-wrap:wrap}.library-view-toggle button,.source-actions button,.source-row button{padding:7px 9px;font-size:12px}.library-view-toggle button[aria-pressed="true"]{background:#3a2b25;outline:2px solid #d2764e}.track-card-copy,.library-group-copy{display:flex;flex-direction:column;gap:4px;min-width:0}.track-meta{color:#8f9b97;font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.library-group-card{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;align-items:center;padding:12px;border-radius:12px;background:#202424}.empty-state{padding:14px;border:1px dashed rgba(255,255,255,.1);border-radius:12px;color:#aeb7b4}.sources{display:grid;gap:10px}.source-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;align-items:center;padding:10px 12px;border-radius:12px;background:#202424}.source-row>div:first-child{display:flex;flex-direction:column;gap:3px;min-width:0}.source-row small{color:#aeb7b4;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.source-candidate{border:1px solid rgba(210,118,78,.25)}.source-discovery-summary{color:#aeb7b4;font-size:13px;margin-top:2px}#sourceList,#sourceDiscovery,#ignoredSourceList{display:grid;gap:7px}#ignoredSources{border-top:1px solid rgba(255,255,255,.07);padding-top:8px}#ignoredSources summary{cursor:pointer;color:#aeb7b4;margin-bottom:8px}#clearIgnoredSources{margin-top:8px;padding:7px 9px;font-size:12px}
@media(max-width:720px){.library-toolbar{grid-template-columns:1fr}.library-view-toggle,.source-actions{width:100%}.source-row,.library-group-card{grid-template-columns:1fr}.source-row-actions{justify-content:flex-start}}

.library-editor,.trash{display:grid;gap:10px;padding-top:4px}.library-editor[hidden],#purgeRecovery[hidden]{display:none}.library-editor{padding:14px;border:1px solid rgba(255,255,255,.08);border-radius:14px;background:#171b1a}.library-editor-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.library-editor-grid label{display:flex;flex-direction:column;gap:5px}.library-editor-grid label>span{color:#aeb7b4;font-size:13px}.library-editor input,.playlist-create input,.playlist-heading input,.track-actions select{border:1px solid rgba(255,255,255,.12);border-radius:9px;padding:8px 9px;background:#202424;color:#f6f2eb;font:inherit}.library-editor-actions,.playlist-create,.playlist-card-actions,.playlist-entry-actions,.trash-actions{display:flex;gap:6px;flex-wrap:wrap}.library-editor-actions button,.playlist-card-actions button,.playlist-entry-actions button,.trash-actions button,#trashRefresh,#recoverTrashPurge{padding:7px 9px;font-size:12px}.track-actions select{max-width:150px;font-size:12px;padding:6px 7px}.playlist-card{grid-template-columns:minmax(0,1fr) auto}.playlist-heading input{width:min(280px,100%);font-weight:700}.playlist-card-actions{justify-content:flex-end}.playlist-entries li{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px;align-items:center;padding:4px 0}.trash-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;align-items:center;padding:11px 12px;border-radius:12px;background:#202424}.trash-row>div:first-child{display:flex;flex-direction:column;gap:3px}.trash-row small,.deleted-row small{color:#aeb7b4}.trash #trashItems{display:grid;gap:7px}.deleted-history{border-top:1px solid rgba(255,255,255,.07);padding-top:8px}.deleted-history summary{cursor:pointer;color:#aeb7b4}.deleted-row{display:flex;justify-content:space-between;gap:10px;padding:5px 0}#purgeRecovery{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px;border:1px solid rgba(255,180,171,.25);border-radius:10px}
@media(max-width:720px){.library-editor-grid{grid-template-columns:1fr}.playlist-card{grid-template-columns:1fr}.playlist-card-actions{justify-content:flex-start}.trash-row{grid-template-columns:1fr}}


/* [VXG RealForever] V3 lived-product geometry over V4 owners.
   Presentation parity is not semantic ownership. */
html,body{height:100%}
body{
 margin:0;
 min-height:100vh;
 padding:0;
 display:block;
 background:#f4f1eb;
 color:#25282a;
 overflow:hidden;
}
.shell{width:100%;height:100vh}
.player.v3-product-shell{
 width:100%;
 height:100vh;
 min-height:0;
 border:0;
 border-radius:0;
 padding:0;
 box-shadow:none;
 background:#f7f5f1;
 display:grid;
 grid-template-columns:190px minmax(0,1fr);
 grid-template-rows:56px 52px minmax(0,1fr) 76px;
 grid-template-areas:
  "header header"
  "sidebar utility"
  "sidebar main"
  "footer footer";
 gap:0;
 overflow:hidden;
}
body[data-sidebar-open="false"] .player.v3-product-shell{
 grid-template-columns:0 minmax(0,1fr);
}
.product-header{
 grid-area:header;
 min-width:0;
 display:flex;
 align-items:center;
 gap:8px;
 padding:8px 12px;
 background:#1f2527;
 color:#f7f7f4;
 border-bottom:1px solid #343c3f;
 z-index:20;
}
.product-header .brand{
 border:0;
 background:transparent;
 color:#f7f7f4;
 padding:7px 8px;
 font-size:17px;
 letter-spacing:-.02em;
}
.product-header .brand span{font-weight:800}
.nav-toggle{
 width:36px;
 height:36px;
 padding:0;
 border-radius:8px;
 background:transparent;
 color:#f7f7f4;
 border:1px solid #3d474a;
}
.top-tabs{display:flex;align-items:center;gap:4px;height:100%}
.top-tabs button{
 height:36px;
 border:0;
 border-radius:8px;
 padding:0 13px;
 background:transparent;
 color:#c7d0d2;
}
.top-tabs button.active,
.top-tabs button[aria-pressed="true"]{
 background:#ffffff14;
 color:#fff;
 outline:none;
}
.header-spacer{flex:1}
.product-header .version{
 max-width:min(480px,36vw);
 overflow:hidden;
 text-overflow:ellipsis;
 white-space:nowrap;
 border:1px solid #3d474a;
 border-radius:999px;
 padding:4px 8px;
 color:#aeb8ba;
 font-size:10px;
}
#exitVexStream{
 background:transparent;
 color:#f7f7f4;
 border-color:#3d474a;
 padding:8px 10px;
}
.sidebar{
 grid-area:sidebar;
 min-width:0;
 min-height:0;
 overflow:auto;
 padding:12px;
 background:#fbf9f5;
 border-right:1px solid #ddd7cd;
 color:#2a2d2e;
}
.sidebar[hidden]{display:none}
.sidebar .nav{display:grid;gap:4px}
.sidebar .nav button{
 display:grid;
 grid-template-columns:24px minmax(0,1fr);
 align-items:center;
 gap:7px;
 width:100%;
 text-align:left;
 border:0;
 background:transparent;
 color:#333638;
 padding:9px 10px;
 border-radius:9px;
}
.sidebar .nav button.active,
.sidebar .nav button[aria-pressed="true"]{
 background:#ece7de;
 color:#191b1c;
 outline:none;
 font-weight:750;
}
.nav-icon{text-align:center;color:#697173}
.sidebar-actions{margin-top:14px;padding-top:12px;border-top:1px solid #e0dbd2}
.sidebar-note{
 margin-top:14px;
 padding-top:12px;
 border-top:1px solid #e0dbd2;
 color:#767b7c;
 font-size:12px;
 line-height:1.45;
}
.library-utility-bar{
 grid-area:utility;
 min-width:0;
 margin:0;
 padding:7px 18px;
 display:grid;
 grid-template-columns:minmax(0,1fr) auto;
 align-items:center;
 gap:10px;
 background:#f7f5f1;
 border-bottom:1px solid #ded8cf;
}
.library-utility-bar[hidden]{display:none}
.library-search{min-width:0;display:flex;align-items:center;gap:6px}
.library-utility-bar .library-search input{
 min-width:0;width:100%;height:38px;border:1px solid #d9d3ca;border-radius:20px;
 padding:8px 12px;background:#fff;color:#2c3031;
}
.search-go{width:38px;height:38px;min-width:38px;padding:0;border-radius:50%;background:#fff;color:#2c3031;border-color:#d9d3ca}
.search-clear{border:0;background:transparent;color:#767c7d;padding:6px 4px}
.toolbar-group{display:flex;align-items:center;gap:8px}
.toolbar-group select,.library-sort-control select{
 height:38px;border:1px solid #d9d3ca;border-radius:9px;padding:0 10px;background:#fff;color:#2c3031;font:inherit;
}
#goDiscoverAdd{height:38px;padding:0 12px;background:#fff;color:#2c3031;border-color:#d9d3ca}
.library-sort-control{display:flex}
.library-sort-control select{height:34px;font-size:12px}
[data-shell-panel]{
 grid-area:main;
 min-width:0;
 min-height:0;
 overflow:auto;
 padding:16px 18px 28px;
 background:#f7f5f1;
 color:#2b2e2f;
}
[data-shell-panel][hidden]{display:none}
.home-view{display:grid;align-content:start;gap:14px}
.home-view .hero{margin:0}
.home-view .stats{
 display:grid;
 grid-template-columns:repeat(4,minmax(0,1fr));
 gap:8px;
 margin:0;
}
.home-view .stat{
 background:#fff;
 border:1px solid #ded8cf;
 border-radius:11px;
 padding:10px;
}
.home-view .stat strong{display:block;font-size:18px}
.home-view .stat span{color:#7a7f80;font-size:12px}
.home-recent{
 background:#fff;
 border:1px solid #ded8cf;
 border-radius:14px;
 padding:13px;
}
#recentSongs{display:block;margin-top:10px}
.home-recent-table-wrap{border-radius:10px}
.home-recent-table{min-width:720px}
.home-recent-table .song-title-cell{min-width:260px}
.queue-drawer{
 position:fixed;
 left:0;
 right:0;
 bottom:76px;
 height:36px;
 z-index:25;
 overflow:hidden;
 display:grid;
 grid-template-rows:36px minmax(0,1fr);
 background:#f7f5f1;
 border-top:1px solid #ddd7cd;
 box-shadow:0 -12px 30px #0002;
 transition:height .22s ease;
}
.queue-drawer.open{height:min(62vh,560px)}
.queue-handle{
 height:36px;
 width:100%;
 border:0;
 border-radius:0;
 padding:0 12px;
 display:flex;
 align-items:center;
 justify-content:center;
 gap:10px;
 background:#fff;
 color:#2c3031;
 border-bottom:1px solid #ddd7cd;
 cursor:ns-resize;
}
.queue-handle:hover{background:#faf8f4}
.grabber{
 width:44px;
 height:5px;
 border-radius:999px;
 background:#b9b7b1;
}
.queue-summary{color:#767c7d;font-size:12px}
.queue-drawer-body{
 min-width:0;
 min-height:0;
 overflow:auto;
 padding:12px 16px 18px;
 background:#fbf9f5;
 color:#2a2d2e;
}
.queue-drawer-body .section-heading{
 position:sticky;
 top:0;
 z-index:2;
 gap:12px;
 padding:4px 0 10px;
 background:#fbf9f5;
}
.queue-drawer-body #queueList li{
 background:#fff;
 color:#646a6b;
 border:1px solid #e0dbd2;
}
.queue-drawer-body #queueList li.current{
 background:#fff0e6;
 color:#2a2d2e;
 border-color:#e6b99f;
}
.queue-drawer-body #queueList li{align-items:start}
.queue-title{display:grid;gap:2px;min-width:0}
.queue-meta{
 min-width:0;
 overflow:hidden;
 text-overflow:ellipsis;
 white-space:nowrap;
 color:#767c7d;
 font-size:12px;
 line-height:1.25;
}
.queue-description{
 color:#5f6667;
 font-size:12px;
 line-height:1.35;
 overflow-wrap:anywhere;
}
.queue-drawer-body #queueList li.current .queue-title strong,
.queue-drawer-body #queueList li.current .queue-meta{
 overflow:visible;
 text-overflow:clip;
 white-space:normal;
 overflow-wrap:anywhere;
}
.player-footer{
 grid-area:footer;
 min-width:0;
 min-height:0;
 height:76px;
 display:grid;
 grid-template-columns:minmax(300px,.95fr) minmax(0,1.7fr);
 background:#fff;
 border-top:1px solid #ddd7cd;
}
.player-footer>.now,
.player-footer>.transport{grid-area:auto;border-top:0}
.now{
 grid-area:now;
 min-width:0;
 display:grid;
 grid-template-columns:52px minmax(0,1fr);
 gap:10px;
 align-items:center;
 padding:7px 14px;
 background:#fff;
 color:#272a2b;
 border-top:1px solid #ddd7cd;
}
.now .art{
 width:52px;
 height:52px;
 border-radius:12px;
 font-size:22px;
 overflow:hidden;
}
.now .art img{width:100%;height:100%;object-fit:cover;display:block}
.now .track-copy{min-width:0}
.now .track-copy strong,
.now .track-copy span{
 overflow:hidden;
 text-overflow:ellipsis;
 white-space:nowrap;
}
.transport{
 grid-area:transport;
 display:grid;
 grid-template-columns:minmax(0,1fr) auto;
 grid-template-rows:auto auto;
 align-content:center;
 gap:2px 16px;
 padding:4px 14px 5px;
 background:#fff;
 border-top:1px solid #ddd7cd;
}
.transport-controls{
 grid-column:1;
 grid-row:1;
 display:flex;
 align-items:center;
 justify-content:center;
 gap:8px;
}
.timeline{
 grid-column:1;
 grid-row:2;
 display:grid;
 grid-template-columns:38px minmax(120px,420px) 38px;
 align-items:center;
 justify-content:center;
 gap:8px;
 color:#747a7b;
 font-size:11px;
 font-variant-numeric:tabular-nums;
}
.timeline span:first-child{text-align:right}
.timeline input[type="range"]{width:100%;accent-color:#c65f39}
.timeline input[type="range"]:disabled{opacity:.45}
.player-aux{
 grid-column:2;
 grid-row:1/3;
 display:flex;
 align-items:center;
 justify-content:flex-end;
 gap:8px;
 min-width:88px;
}
.volume-control{
 height:64px;
 display:grid;
 grid-template-columns:18px auto;
 align-items:center;
 justify-items:center;
 gap:3px;
 color:#747a7b;
 font-size:10px;
}
.volume-control input[type="range"]{
 width:18px;
 height:50px;
 margin:0;
 writing-mode:vertical-lr;
 direction:rtl;
 accent-color:#c65f39;
}
.volume-control span{
 writing-mode:vertical-rl;
 transform:rotate(180deg);
 letter-spacing:.03em;
}
.queue-mini{
 display:flex!important;
 grid-auto-flow:column;
 gap:5px;
 width:auto!important;
 min-width:52px!important;
 padding:0 10px!important;
 font-size:13px!important;
}
.transport button{
 width:42px;
 height:42px;
 min-width:42px;
 padding:0;
 display:grid;
 place-items:center;
 background:#f4f1ec;
 color:#2c3031;
 border-color:#d9d3ca;
 font-size:16px;
}
.transport button.primary{
