.sort-reset{padding:3px 6px!important;font-size:10px!important;background:transparent!important}
.song-sort-head{display:inline-flex;align-items:center;gap:4px;padding:0;border:0;border-radius:0;background:transparent;color:inherit;font:inherit;font-weight:750;text-transform:inherit;letter-spacing:inherit}
