 display:flex;
 align-items:center;
 gap:6px;
 flex-wrap:wrap;
 margin-top:3px;
}
.library-detail-relations[hidden]{display:none}
.library-detail-relation-label{color:#73797a;font-size:11px}
.library-detail-relation{
