 color:#4a4f50;
 border-color:#d9d3ca;
}
@media(max-width:720px){.library-detail-relations{grid-column:1/-1}}

/* Artist detail is its own read-only Library terrain over the current group. */
.artist-detail-section{display:grid;gap:10px;padding:12px;background:#fff;border:1px solid #ded8cf;border-radius:14px}
.artist-detail-section[hidden],.artist-album-shelf[hidden]{display:none}
.artist-section-toggle{
 width:100%;
 display:grid;
 grid-template-columns:auto auto minmax(0,1fr);
 align-items:center;
 gap:8px;
 text-align:left;
 padding:8px 9px;
 background:#faf8f4;
 color:#343839;
 border-color:#ded8cf;
}
.artist-section-count{
 display:inline-grid;
 place-items:center;
 min-width:22px;
 height:20px;
 padding:0 6px;
 border-radius:999px;
 background:#eaded4;
 color:#7d412b;
 font-size:11px;
}
.artist-section-hint{text-align:right;color:#777d7e;font-size:11px;font-weight:500}
.artist-album-shelf{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,190px));gap:9px}
.artist-album-card{
 display:grid;
 grid-template-columns:58px minmax(0,1fr);
 align-items:center;
 gap:9px;
 padding:9px;
 text-align:left;
 background:#fff;
 color:#2d3031;
 border:1px solid #e1dcd3;
 border-radius:11px;
}
.artist-album-card .library-group-cover{width:58px;border-radius:9px}
.artist-album-copy{display:grid;gap:3px;min-width:0}
.artist-album-copy strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.artist-songs-head{display:flex;align-items:end;justify-content:space-between;gap:12px}
.artist-songs-head h3{margin:0}
.artist-mini-search{
