}
.artist-mini-search input{min-width:0;width:100%;border:0;outline:0;padding:8px 0;background:transparent;color:#2d3031;font:inherit}
.artist-album-filter:empty{display:none}
.artist-filter-chip{display:inline-flex;align-items:center;gap:6px;padding:5px 8px;border-radius:999px;background:#fff1e7;border:1px solid #e6b99f;font-size:11px}
.artist-filter-chip button{padding:0 3px;border:0;background:transparent;color:#7d412b}
.artist-song-table-host{min-width:0}
.artist-song-table .col-artist{display:none!important}
