.playlist-entry-actions,.playlist-track-actions{display:flex;gap:4px;align-items:center;justify-content:flex-end;flex-wrap:wrap}
.playlist-entry-actions>button,.playlist-track-actions>button{padding:6px 8px}
.playlist-entry-actions .song-more{position:relative}
@media(max-width:720px){
 .playlist-detail-entries .playlist-entry{grid-template-columns:24px 42px minmax(0,1fr)}
 .playlist-entry-actions{grid-column:2/-1;justify-content:flex-start}
}


/* Fixed Now Playing projects current Library relationships and existing track actions. */
.now-art-button,.now-title-button{
