 padding:0;
 text-align:left;
}
.now-art-button{display:block;width:52px;height:52px;border-radius:12px}
.now-art-button:disabled,.now-title-button:disabled{cursor:default}
.now-art-button:not(:disabled):hover,.now-art-button:not(:disabled):focus-visible,
.now-title-button:not(:disabled):hover,.now-title-button:not(:disabled):focus-visible{
 outline:2px solid #d6a58f;
 outline-offset:2px;
}
.now-title-row{display:flex;align-items:center;gap:5px;min-width:0}
.now-title-button{min-width:0;overflow:hidden;white-space:nowrap;border-radius:4px}
.now-title-button strong{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.now-meta{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#6f7475;font-size:12px}
.now-relation{border:0;background:transparent;color:inherit;padding:0;font:inherit;text-decoration:underline;text-decoration-color:#b7b2a9;text-underline-offset:2px}
.now-relation:hover,.now-relation:focus-visible{color:#a85435;outline:none}
.now-relation-static{color:#777d7e}
.now-details{position:relative}
.now-details[hidden]{display:none}
.now-details-toggle{list-style:none;cursor:pointer;padding:2px 5px;border-radius:6px;color:#6f7475}
.now-details-toggle::-webkit-details-marker{display:none}
.now-details-toggle:hover,.now-details-toggle:focus-visible{background:#ece6dd;color:#25282a;outline:none}
.now-details-menu{right:0;left:auto;bottom:calc(100% + 7px);top:auto;min-width:180px;z-index:60}


/* Track Details projects existing Library source/provenance and playback-window truth. */
.track-details-notice{
 display:grid;
 gap:3px;
 padding:10px 12px;
 border:1px solid #c8ddd1;
 border-radius:11px;
 background:#f4faf7;
 color:#28594a;
}
.track-details-notice span{font-size:12px;color:#557069}
.playback-window-summary{
 display:flex;
 align-items:center;
 gap:7px;
 flex-wrap:wrap;
 padding:9px 11px;
 border-radius:10px;
 background:#faf8f4;
 border:1px solid #ded8cf;
 font-size:12px;
}
.playback-window-summary span{color:#6f7475}
.track-source-panel{
 border-top:1px solid #ded8cf;
 padding-top:10px;
}
.track-source-panel summary{cursor:pointer;font-weight:700}
.track-source-details{display:grid;gap:0;margin:9px 0}
.track-source-row{
 display:grid;
 grid-template-columns:minmax(110px,150px) minmax(0,1fr);
 gap:10px;
 padding:7px 0;
 border-top:1px solid #ebe6df;
 font-size:12px;
}
.track-source-row:first-child{border-top:0}
.track-source-row span{min-width:0;overflow-wrap:anywhere;color:#6f7475}
@media(max-width:720px){.track-source-row{grid-template-columns:1fr;gap:3px}}



/* V3 generic modal geometry restored verbatim in shape for phone pairing. */
.modal-backdrop{position:fixed;inset:0;background:#0008;z-index:80;display:flex;align-items:center;justify-content:center;padding:16px}
.modal-backdrop[hidden]{display:none}
.modal-card{width:min(600px,96vw);max-height:88vh;overflow:auto;background:#f4f1eb;color:#25282a;border:1px solid #dfddd7;border-radius:16px;box-shadow:0 18px 70px #0005;padding:16px}
.modal-actions{display:flex;justify-content:flex-end;gap:8px;flex-wrap:wrap;margin-top:14px}
.modal-card button{border:1px solid #dfddd7;background:white;color:#25282a;border-radius:9px;padding:8px 11px}
.modal-card button.primary{background:#bb5731;border-color:#bb5731;color:white}
.modal-card .small,.modal-card .muted{color:#6b7579}
.modal-card .notice{background:#fff7e5;border:1px solid #ead3a6;border-radius:10px;padding:10px;color:#25282a}
.modal-card .notice.success{background:#e9f3ee;border-color:#c8ddd1}
.modal-card .issue{border:1px solid #dfddd7;background:white;border-radius:12px;padding:11px;margin-top:9px;color:#25282a}
.modal-card .issue.info{border-color:#b7d5c8}
.modal-card .lifecycle-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px;padding:9px;border:1px solid #dfddd7;border-radius:10px;background:white;color:#25282a}



/* Human-controlled song density: direct column resize + bounded overflow reveal. */
:root{
 --song-col-title:300px;
 --song-col-added:80px;
 --song-col-artist:120px;
 --song-col-album:140px;
 --song-col-genre:90px;
 --song-col-duration:60px;
 --song-table-min-width:812px;
 --song-home-table-min-width:782px;
}
.song-table{width:var(--song-table-min-width);min-width:var(--song-table-min-width)}
.home-recent-table{min-width:var(--song-home-table-min-width)}
.song-table .song-title-cell{width:var(--song-col-title)!important;min-width:0}
.song-table .col-added{width:var(--song-col-added)!important}
.song-table .col-artist{width:var(--song-col-artist)!important;min-width:0}
.song-table .col-album{width:var(--song-col-album)!important;min-width:0}
.song-table .col-genre{width:var(--song-col-genre)!important;min-width:0}
.song-table .col-duration{width:var(--song-col-duration)!important}

.song-table th[data-song-column]{
 position:sticky;
 padding-right:14px;
}
.song-column-resizer{
 position:absolute;
 z-index:4;
 top:0;
 right:-4px;
 width:9px;
 height:100%;
 cursor:col-resize;
 touch-action:none;
}
.song-column-resizer::after{
 content:"";
 position:absolute;
 top:22%;
 bottom:22%;
 left:4px;
 width:1px;
 background:#c8c1b7;
 opacity:0;
 transition:opacity .12s ease,background .12s ease;
}
.song-table th[data-song-column]:hover .song-column-resizer::after,
.song-column-resizer:hover::after,
.song-column-resizer:focus-visible::after{
 opacity:1;
 background:#9d765f;
}
.song-column-resizer:focus-visible{
 outline:2px solid #d6a58f;
 outline-offset:-2px;
}
body.song-column-resizing,
body.song-column-resizing *{cursor:col-resize!important;user-select:none!important}

.song-marquee{
 display:block;
 min-width:0;
 max-width:100%;
 overflow:hidden;
 white-space:nowrap;
 text-overflow:ellipsis;
}
.song-marquee-text{
 display:inline-block;
 min-width:max-content;
 white-space:nowrap;
 transform:translateX(0);
 will-change:transform;
}
.song-table tbody tr:hover .song-marquee.overflowing .song-marquee-text,
.song-table tbody tr:focus-within .song-marquee.overflowing .song-marquee-text,
.song-table tbody tr.playing .song-marquee.overflowing .song-marquee-text,
.home-recent-table tbody tr:hover .song-marquee.overflowing .song-marquee-text,
.home-recent-table tbody tr:focus-within .song-marquee.overflowing .song-marquee-text,
.home-recent-table tbody tr.playing .song-marquee.overflowing .song-marquee-text{
 animation:song-overflow-reveal var(--song-marquee-duration,6.5s) linear .65s infinite alternate;
}
@keyframes song-overflow-reveal{
 0%,10%{transform:translateX(0)}
 90%,100%{transform:translateX(calc(0px - var(--song-marquee-shift,0px)))}
}
@media(prefers-reduced-motion:reduce){
 .song-marquee-text{animation:none!important;transform:none!important}
}


/* V3 YouTube review is an in-place Discover step over the V4 Import owners. */
.youtube-import .import-review{
 grid-area:auto;
 z-index:auto;
 align-self:stretch;
 justify-self:stretch;
 width:100%;
 max-height:none;
 overflow:visible;
 margin:0;
 background:#fff;
 color:#2c3031;
 border:1px solid #ded8cf;
 box-shadow:none;
}
.import-runtime-status{
 display:flex;
 align-items:center;
 justify-content:space-between;
 gap:10px;
 flex-wrap:wrap;
 padding:11px 13px;
