 font-size:13px;
}
.import-runtime-status strong{color:#2c3031}
.import-runtime-status[data-ready="true"]{
 border-color:#c9d9c8;
 background:#f5faf4;
}
.import-runtime-status button{padding:7px 9px;font-size:12px}


/* Import lived path: preserve source identity from review through Library completion. */
.youtube-import-entry[hidden]{display:none}
.import-review-source{
 display:grid;
 grid-template-columns:152px minmax(0,1fr);
 gap:14px;
 align-items:center;
 padding:12px;
