 border-radius:12px;
 background:#fbfaf7;
}
.import-review-thumbnail{
 width:152px;
 aspect-ratio:16/9;
 object-fit:cover;
 border-radius:9px;
 background:#ebe7df;
}
.import-review-thumbnail.fallback{
 display:grid;
 place-items:center;
 color:#858b8c;
 font-size:28px;
}
.import-review-thumbnail[hidden]{display:none}
.import-review-source-copy{
 min-width:0;
 display:grid;
 gap:4px;
}
.import-review-source-copy strong{
 font-size:16px;
