 gap:12px;
 color:#2c3031;
}
.import-activity-group-head>div{
 display:grid;
 gap:2px;
}
.import-activity-group-head span{
 color:#858b8c;
 font-size:12px;
}
.import-activity-count{
 min-width:25px;
 height:25px;
 padding:0 7px;
 display:grid;
 place-items:center;
 border-radius:999px;
 background:#ece7de;
 color:#333839!important;
 font-weight:750;
}
.import-activity-list{
 display:grid;
 gap:8px;
}
.import-activity-empty{
 padding:13px;
 border:1px dashed #d9d3ca;
 border-radius:11px;
 color:#858b8c;
 background:#fff;
}
.import-job{
 display:grid;
 grid-template-columns:112px minmax(0,1fr) auto;
 gap:12px;
 align-items:center;
 padding:11px 12px;
 border:1px solid #e1dcd3;
 border-radius:12px;
 background:#fff;
 color:#2d3031;
}
.import-job-thumbnail{
 width:112px;
 aspect-ratio:16/9;
 object-fit:cover;
 border-radius:9px;
 background:#ebe7df;
}
.import-job-thumbnail.fallback{
 display:grid;
 place-items:center;
 color:#858b8c;
 font-size:22px;
}
.import-job-main{
