 gap:3px;
}
.import-job-title-row{
 display:flex;
 align-items:center;
 gap:7px;
 min-width:0;
}
.import-job-title-row>strong{
 min-width:0;
 overflow:hidden;
 text-overflow:ellipsis;
 white-space:nowrap;
}
.import-job-status{
 flex:0 0 auto;
 padding:2px 7px;
 border-radius:999px;
 background:#eeeae3;
 color:#5b6263;
 font-size:10px;
 font-weight:750;
}
.import-job-status.status-running,
.import-job-status.status-queued,
.import-job-status.status-committing{
 background:#e9f2ed;
 color:#355d4e;
}
.import-job-status.status-ready{
 background:#fff3d8;
 color:#72561c;
}
.import-job-status.status-done{
